lemma HasAdjFDerivAt.comp {f : F → G} {g : E → F} {f' g'} {x : E}
    (hf : HasAdjFDerivAt 𝕜 f f' (g x)) (hg : HasAdjFDerivAt 𝕜 g g' x) :
    HasAdjFDerivAt 𝕜 (fun x => f (g x)) (fun dz => g' (f' dz)) x where

lemma HasAdjFDerivAt.prodMk {f : E → F} {g : E → G} {f' g'} {x : E}
    (hf : HasAdjFDerivAt 𝕜 f f' x) (hg : HasAdjFDerivAt 𝕜 g g' x) :
    HasAdjFDerivAt 𝕜 (fun x => (f x, g x)) (fun dyz => f' dyz.fst + g' dyz.snd) x where

lemma HasAjdFDerivAt.add {f g : E → F} {f' g'} {x : E}
    (hf : HasAdjFDerivAt 𝕜 f f' x) (hg : HasAdjFDerivAt 𝕜 g g' x) :
    HasAdjFDerivAt 𝕜 (fun x => f x + g x) (fun dy => f' dy + g' dy) x where

lemma adjFDeriv_sub [CompleteSpace E] [CompleteSpace F] {f g : E → F} {x : E}
    (hf : DifferentiableAt 𝕜 f x) (hg : DifferentiableAt 𝕜 g x) :
    adjFDeriv 𝕜 (fun x => f x - g x) x = fun dy => adjFDeriv 𝕜 f x dy - adjFDeriv 𝕜 g x dy

lemma exists_of_mem_uniqueMap4 {T : FourTree α1 α2 α3 α4}
    (C : α1 × α2 × α3 × α4) (h : C ∈ T.uniqueMap4 f) :
    ∃ qHd qHu Q5 Q10, C = (qHd, qHu, Q5, f Q10) ∧ (qHd, qHu, Q5, Q10) ∈ T

@[inherit_doc HasAdjoint]
noncomputable
def adjoint (f : E → F)

lemma HasAdjoint.adjoint
    {f : E → F} {f' : F → E}
    (hf : HasAdjoint 𝕜 f f') : adjoint 𝕜 f = f'

lemma HasAdjoint.comp {f : F → G} {g : E → F} {f' g'}
    (hf : HasAdjoint 𝕜 f f') (hg : HasAdjoint 𝕜 g g') :
    HasAdjoint 𝕜 (fun x : E => f (g x)) (fun x => g' (f' x))

lemma HasAdjoint.prodMk {f : E → F} {g : E → G} {f' g'}
    (hf : HasAdjoint 𝕜 f f') (hg : HasAdjoint 𝕜 g g') :
    HasAdjoint 𝕜 (fun x : E => (f x, g x)) (fun yz => f' yz.1 + g' yz.2)

lemma HasAdjoint.add {f g : E → F} {f' g'}
    (hf : HasAdjoint 𝕜 f f') (hg : HasAdjoint 𝕜 g g') :
    HasAdjoint 𝕜 (fun x : E => f x + g x) (fun y => f' y + g' y)

lemma HasAdjoint.sub {f g : E → F} {f' g'}
    (hf : HasAdjoint 𝕜 f f') (hg : HasAdjoint 𝕜 g g') :
    HasAdjoint 𝕜 (fun x : E => f x - g x) (fun y => f' y - g' y)

lemma smooth_R {F : (X → U) → (X → V)} {F' : (X → V) → (X → U)} {u : X → U}
    (h : HasVarAdjDerivAt F F' u) {φ : ℝ → X → U} (hφ : ContDiff ℝ ∞ ↿φ) (x : X) :
    ContDiff ℝ ∞ (fun s : ℝ => F (fun x' => φ s x') x)

lemma smooth_linear {F : (X → U) → (X → V)} {F' : (X → V) → (X → U)} {u : X → U}
    (h : HasVarAdjDerivAt F F' u) {φ : ℝ → X → U} (hφ : ContDiff ℝ ∞ ↿φ) :
    ContDiff ℝ ∞ (fun s' : ℝ => F (fun x => φ 0 x + s' • deriv (φ · x) 0) x)

lemma differentiable_linear {F : (X → U) → (X → V)} {F' : (X → V) → (X → U)} {u : X → U}
    (h : HasVarAdjDerivAt F F' u) {φ : ℝ → X → U} (hφ : ContDiff ℝ ∞ ↿φ) (x : X) :
    Differentiable ℝ (fun s' : ℝ => F (fun x => φ 0 x + s' • deriv (φ · x) 0) x)

lemma comp {F : (Y → V) → (Z → W)} {G : (X → U) → (Y → V)} {u : X → U}
    {F' G'} (hF : HasVarAdjDerivAt F F' (G u)) (hG : HasVarAdjDerivAt G G' u) :
    HasVarAdjDerivAt (fun u => F (G u)) (fun ψ => G' (F' ψ)) u where

lemma comp {F : (Y → V) → (Z → W)} {G : (X → U) → (Y → V)} {F' G'}
    (hF : HasVarAdjoint F F') (hG : HasVarAdjoint G G') :
    HasVarAdjoint (fun φ => F (G φ)) (fun φ => G' (F' φ)) where

lemma congr_fun {F G : (X → U) → (Y → V)} {F' : (Y → V) → (X → U)}
    (h : HasVarAdjoint G F') (h' : ∀ φ, IsTestFunction φ → F φ = G φ) :
    HasVarAdjoint F F' where

lemma neg {F : (X → U) → (X → V)} {F' : (X → V) → (X → U)}
    (hF : HasVarAdjoint F F') :
    HasVarAdjoint (fun φ x => - F φ x) (fun φ x => - F' φ x) where

lemma add {F G : (X → U) → (X → V)} {F' G' : (X → V) → (X → U)}
    (hF : HasVarAdjoint F F') (hG : HasVarAdjoint G G') :
    HasVarAdjoint (fun φ x => F φ x + G φ x) (fun φ x => F' φ x + G' φ x) where

lemma sub {F G : (X → U) → (X → V)} {F' G' : (X → V) → (X → U)}
